#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Telnyx setup for the AI business card.
# Stages 1-4 are portal steps you do by hand. Stages 5-6 run by API with the
# key from stage 2. Re-running is safe: saved values are kept, and an existing
# application is reused.
# ──────────────────────────────────────────────────────────────────────────

TELNYX_API="https://api.telnyx.com/v2"
APP_NAME="${APP_NAME:-ai-business-card}"
PLACEHOLDER_WEBHOOK="https://example.com/webhooks/telnyx"

# telnyx_api METHOD PATH [JSON_BODY]: prints the response body; returns 1 on a
# non-2xx status after showing the error. Needs $TELNYX_API_KEY.
telnyx_api() {
  local method="$1" path="$2" body="${3:-}" resp status
  if [[ -n "$body" ]]; then
    resp=$(curl -sS -w '\n%{http_code}' -X "$method" "$TELNYX_API$path" \
      -H "Authorization: Bearer $TELNYX_API_KEY" -H "Content-Type: application/json" -H "Accept: application/json" \
      --data "$body")
  else
    resp=$(curl -sS -w '\n%{http_code}' -X "$method" "$TELNYX_API$path" \
      -H "Authorization: Bearer $TELNYX_API_KEY" -H "Accept: application/json")
  fi
  status="${resp##*$'\n'}"
  resp="${resp%$'\n'*}"
  if [[ "$status" != 2* ]]; then
    warn "Telnyx API $method $path returned HTTP $status" >&2
    note "$(printf '%s' "$resp" | head -c 600)" >&2
    return 1
  fi
  printf '%s' "$resp"
}

# json_get EXPR reads JSON on stdin and prints the Python expression over `d`.
json_get() { python3 -c 'import json,sys; d=json.load(sys.stdin); print('"$1"')'; }

# e164 NUMBER normalises a US number: keeps digits, adds +1 when 10 digits.
e164() {
  local digits; digits=$(printf '%s' "$1" | tr -cd '0-9')
  if [[ ${#digits} -eq 10 ]]; then printf '+1%s' "$digits"
  elif [[ ${#digits} -eq 11 && "$digits" == 1* ]]; then printf '+%s' "$digits"
  else printf '+%s' "$digits"; fi
}

run_wizard() {

TOTAL_STAGES=6

banner "Telnyx setup for the AI business card"

# ── 1. Sign in ─────────────────────────────────────────────────────────────
stage "Telnyx: sign in"
say "This wizard needs your Telnyx account open in the browser."
open_url "https://portal.telnyx.com"
step "Sign in to Mission Control Portal."
note "You said the account exists and has credit. A number costs about \$1.00 per month."
pause "Signed in? Press Enter."

# ── 2. API key ─────────────────────────────────────────────────────────────
stage "Telnyx: API key"
say "The server uses this key for every Telnyx API call. It is a secret."
open_url "https://portal.telnyx.com/#/app/api-keys"
step "On the API Keys page, click 'Create API Key'."
step "Copy the key now. Telnyx shows it only once. It starts with KEY."
ask_secret TELNYX_API_KEY "Paste the API key:"
write_env TELNYX_API_KEY "$TELNYX_API_KEY"
say "Checking the key against the Telnyx API..."
if balance=$(telnyx_api GET /balance); then
  say "Key works. Account balance: $(printf '%s' "$balance" | json_get 'str(d["data"].get("balance")) + " " + str(d["data"].get("currency",""))')"
else
  warn "The key did not work. Re-run this wizard and paste it again; later stages need it."
  exit 1
fi

# ── 3. Public key ──────────────────────────────────────────────────────────
stage "Telnyx: public key"
say "Telnyx signs every webhook with Ed25519. The server verifies the signature with this public key."
open_url "https://portal.telnyx.com/#/api-keys/public-key"
step "Open the 'Public Key' tab on the API Keys page."
step "Copy the public key. It is a Base64 string, about 44 characters, and it is not secret."
ask TELNYX_PUBLIC_KEY "Paste the public key:"
write_env TELNYX_PUBLIC_KEY "$TELNYX_PUBLIC_KEY"

# ── 4. Phone number ────────────────────────────────────────────────────────
stage "Telnyx: phone number"
say "Buy one US local number with the Voice feature. This is the number callers dial."
open_url "https://portal.telnyx.com/#/app/numbers/search-numbers"
note "If that page does not open the number search, use the left menu: Numbers → Search & Buy Numbers."
step "Filter: Country = United States, Type = Local, Features = Voice. Pick an area code you like."
step "Add one number to the cart and complete the purchase."
step "Then open Numbers → My Numbers and copy the number."
ask TELNYX_PHONE_NUMBER "Paste the number (any format, e.g. 212 555 0100):"
TELNYX_PHONE_NUMBER=$(e164 "$TELNYX_PHONE_NUMBER")
say "Stored as $TELNYX_PHONE_NUMBER"
write_env TELNYX_PHONE_NUMBER "$TELNYX_PHONE_NUMBER"

# ── 5. Voice API application (by API) ──────────────────────────────────────
stage "Telnyx: Voice API application"
say "The application tells Telnyx where to send call events. The server owns the webhook URL,"
say "so this wizard creates the application by API with webhook format v2."
existing_app=$(_existing TELNYX_APP_ID || true)
if [[ -n "$existing_app" ]] && telnyx_api GET "/call_control_applications/$existing_app" >/dev/null; then
  say "Application $existing_app already exists in .env. Keeping it."
  TELNYX_APP_ID="$existing_app"
else
  note "The webhook URL is a placeholder until the M2 server runs. The server sets it from PUBLIC_URL at startup."
  say "If you already have a fixed ngrok domain, paste it now. Otherwise press Enter."
  ask PUBLIC_URL "Public HTTPS URL (optional, e.g. https://my-name.ngrok-free.app):" || PUBLIC_URL=""
  webhook_url="$PLACEHOLDER_WEBHOOK"
  if [[ -n "$PUBLIC_URL" ]]; then
    PUBLIC_URL="${PUBLIC_URL%/}"
    write_env PUBLIC_URL "$PUBLIC_URL"
    webhook_url="$PUBLIC_URL/webhooks/telnyx"
  fi
  if confirm "Create Voice API application '$APP_NAME' with webhook $webhook_url?"; then
    created=$(telnyx_api POST /call_control_applications "$(printf '{"application_name":"%s","webhook_event_url":"%s","webhook_api_version":"2","webhook_timeout_secs":25}' "$APP_NAME" "$webhook_url")") || exit 1
    TELNYX_APP_ID=$(printf '%s' "$created" | json_get 'd["data"]["id"]')
    say "Created application $TELNYX_APP_ID"
  else
    warn "Skipped. Create the application in the portal (Voice → Programmable Voice) and paste its ID."
    ask TELNYX_APP_ID "Voice API application ID:"
  fi
fi
write_env TELNYX_APP_ID "$TELNYX_APP_ID"

# ── 6. Connect the number to the application (by API) ──────────────────────
stage "Telnyx: connect the number"
say "Calls to $TELNYX_PHONE_NUMBER must reach application $TELNYX_APP_ID."
numbers=$(telnyx_api GET "/phone_numbers?page%5Bsize%5D=250") || exit 1
number_id=$(printf '%s' "$numbers" | json_get 'next((n["id"] for n in d["data"] if n.get("phone_number")=="'"$TELNYX_PHONE_NUMBER"'"), "")')
if [[ -z "$number_id" ]]; then
  warn "The number $TELNYX_PHONE_NUMBER is not in your account yet. Numbers can take a minute to appear."
  pause "Wait a moment, then press Enter to retry."
  numbers=$(telnyx_api GET "/phone_numbers?page%5Bsize%5D=250") || exit 1
  number_id=$(printf '%s' "$numbers" | json_get 'next((n["id"] for n in d["data"] if n.get("phone_number")=="'"$TELNYX_PHONE_NUMBER"'"), "")')
  [[ -n "$number_id" ]] || { warn "Still not found. Check the number in Numbers → My Numbers and re-run."; exit 1; }
fi
updated=$(telnyx_api PATCH "/phone_numbers/$number_id" "$(printf '{"connection_id":"%s"}' "$TELNYX_APP_ID")") || exit 1
linked=$(printf '%s' "$updated" | json_get 'd["data"].get("connection_id","")')
if [[ "$linked" == "$TELNYX_APP_ID" ]]; then
  say "Connected. Calls to $TELNYX_PHONE_NUMBER now go to application $TELNYX_APP_ID."
else
  warn "Telnyx reports connection_id=$linked. Check the number in the portal."
fi

finish
say "Next: M2. Start ngrok and the server; the server sets the webhook URL from PUBLIC_URL."
}

run_wizard "$@"; exit
